using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments (dispatchers see all, customers see their own)
        group.MapGet("/", async (ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");

            var query = isDispatcher
                ? db.Shipments.AsQueryable()
                : db.Shipments.Where(s => s.CustomerId == user.Id);

            var shipments = await query
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new
                {
                    s.Id,
                    s.TrackingNumber,
                    s.Origin,
                    s.Destination,
                    Status = s.Status.ToString(),
                    s.CreatedAt,
                    s.EstimatedDelivery,
                    s.Notes,
                    s.CustomerId,
                    s.DispatcherId
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // GET single shipment by tracking number
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null) return Results.NotFound();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher && shipment.CustomerId != user.Id)
                return Results.Forbid();

            return Results.Ok(new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.Notes,
                shipment.CustomerId,
                shipment.DispatcherId
            });
        });

        // POST create shipment (dispatchers only)
        group.MapPost("/", async (CreateShipmentRequest request, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher) return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                CustomerId = request.CustomerId,
                EstimatedDelivery = request.EstimatedDelivery,
                Notes = request.Notes,
                DispatcherId = user.Id,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.Notes,
                shipment.CustomerId,
                shipment.DispatcherId
            });
        });

        // PUT update shipment status (dispatchers only)
        group.MapPut("/{id:int}", async (int id, UpdateShipmentRequest request, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher) return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            if (Enum.TryParse<ShipmentStatus>(request.Status, out var status))
                shipment.Status = status;

            if (request.EstimatedDelivery.HasValue)
                shipment.EstimatedDelivery = request.EstimatedDelivery;

            if (request.Notes is not null)
                shipment.Notes = request.Notes;

            shipment.DispatcherId = user.Id;
            await db.SaveChangesAsync();

            return Results.Ok(new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.Notes,
                shipment.CustomerId,
                shipment.DispatcherId
            });
        });
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

public record CreateShipmentRequest(string Origin, string Destination, string CustomerId, DateTime? EstimatedDelivery, string? Notes);
public record UpdateShipmentRequest(string Status, DateTime? EstimatedDelivery, string? Notes);

