@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject ShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h2>Shipments</h2>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination or tracking #..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th @onclick='() => SetSort("TrackingNumber")' style="cursor:pointer">
                    Tracking # @SortIndicator("TrackingNumber")
                </th>
                <th @onclick='() => SetSort("Destination")' style="cursor:pointer">
                    Destination @SortIndicator("Destination")
                </th>
