@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string statusFilter = string.Empty;
    private int? selectedId;

    // Update form
    private ShipmentDto? editingShipment;
    private string newStatus = string.Empty;
    private DateTime? newEstimatedDelivery;
    private string? newNotes;
    private bool saving;
    private string? updateMessage;

    // Create form
    private string createOrigin = string.Empty;
    private string createDestination = string.Empty;
    private string createCustomerId = string.Empty;
    private DateTime? createEstDelivery;
    private string? createNotes;
    private bool creating;
    private string? createMessage;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
        loading = false;
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s => string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);

    private void SelectForUpdate(ShipmentDto s)
    {
        editingShipment = s;
        selectedId = s.Id;
        newStatus = s.Status;
        newEstimatedDelivery = s.EstimatedDelivery;
        newNotes = s.Notes;
        updateMessage = null;
    }

    private void CancelEdit()
    {
        editingShipment = null;
        selectedId = null;
    }

    private async Task SaveUpdate()
    {
        if (editingShipment is null) return;
        saving = true;
        updateMessage = null;

        var result = await ShipmentService.UpdateShipmentAsync(editingShipment.Id, new UpdateShipmentStatusDto
        {
            Status = newStatus,
            EstimatedDelivery = newEstimatedDelivery,
            Notes = newNotes
        });

        if (result is not null)
        {
            updateMessage = "Updated successfully!";
            // Refresh list
            shipments = await ShipmentService.GetShipmentsAsync();
            editingShipment = result;
        }
        else
        {
            updateMessage = "Update failed.";
        }

        saving = false;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(createOrigin) || string.IsNullOrWhiteSpace(createDestination) || string.IsNullOrWhiteSpace(createCustomerId))
        {
            createMessage = "Please fill in Origin, Destination, and Customer ID.";
            return;
        }

        creating = true;
        createMessage = null;

        var result = await ShipmentService.CreateShipmentAsync(new CreateShipmentDto
        {
            Origin = createOrigin,
            Destination = createDestination,
            CustomerId = createCustomerId,
            EstimatedDelivery = createEstDelivery,
            Notes = createNotes
        });

        if (result is not null)
        {
            createMessage = $"Created: {result.TrackingNumber}";
            shipments = await ShipmentService.GetShipmentsAsync();
            createOrigin = createDestination = createCustomerId = string.Empty;
            createEstDelivery = null;
            createNotes = null;
        }
        else
        {
            createMessage = "Creation failed. Check permissions.";
        }

        creating = false;
    }

    private static string GetBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

