@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject ShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260625-123456)"
                   @bind="trackingNumber" @onkeypress="HandleKeyPress" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h6>Route</h6>
                    <p><strong>From:</strong> @shipment.Origin</p>
                    <p><strong>To:</strong> @shipment.Destination</p>
                </div>
                <div class="col-md-6">
                    <h6>Status</h6>
                    <p>
                        <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">
                            @shipment.Status
                        </span>
                    </p>
                    <p><strong>Estimated Delivery:</strong>
                        @(shipment.EstimatedDelivery?.ToString("dddd, MMMM dd, yyyy") ?? "Not yet scheduled")</p>
                </div>
            </div>

            @if (shipment.Notes is not null)
            {
                <div class="mt-3">
                    <h6>Notes</h6>
                    <p>@shipment.Notes</p>
                </div>
            }

            <!-- Progress visualization -->
            <div class="mt-4">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>
        <div class="card-footer text-muted">
            Created: @shipment.CreatedAt.ToString("g")
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool searching;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        errorMessage = null;
        shipment = null;

        shipment = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());

        if (shipment is null)
            errorMessage = "Shipment not found. Please check the tracking number and try again.";

        searching = false;
    }

    private async Task HandleKeyPress(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Cancelled" => 100,
        _ => 0
    };
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject ShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h2>Shipments</h2>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination or tracking #..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th @onclick='() => SetSort("TrackingNumber")' style="cursor:pointer">
                    Tracking # @SortIndicator("TrackingNumber")
                </th>
                <th @onclick='() => SetSort("Destination")' style="cursor:pointer">
                    Destination @SortIndicator("Destination")
                </th>
                <th @onclick='() => SetSort("Status")' style="cursor:pointer">
                    Status @SortIndicator("Status")
                </th>
                <th @onclick='() => SetSort("EstimatedDelivery")' style="cursor:pointer">
                    Est. Delivery @SortIndicator("EstimatedDelivery")
                </th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <button class="btn btn-sm btn-primary" @onclick="() => ShowDetails(shipment)">
                            Details
                        </button>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@if (selectedShipment is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Shipment @selectedShipment.TrackingNumber</h5>
                    <button type="button" class="btn-close" @onclick="CloseDetails"></button>
                </div>
                <div class="modal-body">
                    <dl>
                        <dt>Origin</dt><dd>@selectedShipment.Origin</dd>
                        <dt>Destination</dt><dd>@selectedShipment.Destination</dd>
                        <dt>Status</dt><dd>@selectedShipment.Status</dd>
                        <dt>Created</dt><dd>@selectedShipment.CreatedAt.ToString("g")</dd>
                        <dt>Estimated Delivery</dt><dd>@(selectedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</dd>
                        <dt>Notes</dt><dd>@(selectedShipment.Notes ?? "None")</dd>
                    </dl>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CloseDetails">Close</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string filterText = string.Empty;
    private string sortColumn = "CreatedAt";
    private bool sortAscending = false;
    private ShipmentDto? selectedShipment;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
        loading = false;
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(filterText)
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            .OrderBy(s => sortColumn switch
            {
                "TrackingNumber" => s.TrackingNumber as object,
                "Destination" => s.Destination,
                "Status" => s.Status,
                "EstimatedDelivery" => s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "9999",
                _ => s.CreatedAt.ToString("o")
            }, sortAscending ? Comparer<object>.Default : Comparer<object>.Create((a, b) => Comparer<object>.Default.Compare(b, a)));

    private void SetSort(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column) =>
        sortColumn == column ? (sortAscending ? "▲" : "▼") : "";

    private void ShowDetails(ShipmentDto shipment) => selectedShipment = shipment;
    private void CloseDetails() => selectedShipment = null;

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

